import{_ as r,a0 as l,w as o,s as p,ao as d,I as n,x as i,a1 as a,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 字符界面中获取天气预报 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 字符界面中获取天气预报 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 字符界面中获取天气预报 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 字符界面中获取天气预报 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171013 Get Your Weather Forecast From the Linux CLI","title":"在 Linux 字符界面中获取天气预报","tag":"201801","desc":""},"relativePath":"201801/20171013 Get Your Weather Forecast From the Linux CLI.md","filePath":"[post].md"}'),h={name:"201801/20171013 Get Your Weather Forecast From the Linux CLI.md"};function g(c,t,u,k,b,f){const e=l("Link");return o(),p("div",null,[t[13]||(t[13]=d(`<h1 id="在-linux-字符界面中获取天气预报" tabindex="-1">在 Linux 字符界面中获取天气预报 <a class="header-anchor" href="#在-linux-字符界面中获取天气预报" aria-label="Permalink to “在 Linux 字符界面中获取天气预报”">​</a></h1><p><strong>目标：</strong>使用 Linux 命令行显示天气预报。</p><p><strong>发行版：</strong>所有 Linux 发行版。</p><p><strong>要求：</strong>能连上因特网的 Linux</p><p><strong>难度：</strong>容易</p><p><strong>约定：</strong></p><ul><li><code>#</code> - 需要使用 root 权限来执行指定命令，可以直接使用 root 用户来执行也可以使用 <code>sudo</code> 命令</li><li><code>$</code> - 可以使用普通用户来执行指定命令</li></ul><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h3><p>无需打开网页浏览器就能直接从终端获取最新的天气预报那该多方便啊，对吧？你还能把它写成脚本，或者设置定义定时任务。</p><p><code>http://wttr.in</code> 是一个允许你搜索世界各地天气预报的网站，而且它的是以 ASCII 字符的形式来显示结果的。通过使用 <code>cURL</code> 访问 <code>http://wttr.in</code>，就能直接在终端显示查询结果了。</p><h3 id="获取所在地的天气" tabindex="-1">获取所在地的天气 <a class="header-anchor" href="#获取所在地的天气" aria-label="Permalink to “获取所在地的天气”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-local.jpg" alt="Local weather from wttr.in"></p><p>要抓取所在地的天气情况非常简单。<code>wttr.in</code> 会自动根据 IP 地址来探测你的所在地。除非你用了 VPN，否则它的精度还不错。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in</span></span></code></pre></div><h3 id="获取指定城市的天气" tabindex="-1">获取指定城市的天气 <a class="header-anchor" href="#获取指定城市的天气" aria-label="Permalink to “获取指定城市的天气”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-city.jpg" alt="Weather by city from wttr.in"></p><p>你可以通过在 <code>wttr.in</code> 后加上斜杠和城市名称的方式来获得其他城市的天气情况。不过要把名字中的空格替换成 <code>+</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/New+York</span></span></code></pre></div><p>你也可以以 Unix 时区的形式来填写城市名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/New_York</span></span></code></pre></div><p>不要直接使用空格，否则会出现奇怪而不准确的结果。</p><h3 id="获取机场天气" tabindex="-1">获取机场天气 <a class="header-anchor" href="#获取机场天气" aria-label="Permalink to “获取机场天气”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-airport.jpg" alt="Weather by airport from wttr.in"></p><p>若你对地区的三位机场代号很熟悉，你也可以使用机场代号来查询天气。一般来说使用机场要比使用城市更贴近你，而且更精确一些。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/JFK</span></span></code></pre></div><h3 id="猜测所在地" tabindex="-1">猜测所在地 <a class="header-anchor" href="#猜测所在地" aria-label="Permalink to “猜测所在地”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-landmark.jpg" alt="Weather by landmark from wttr.in"></p><p>通过使用 <code>~</code> 字符，你可以让 <code>wttr.in</code> 通过地标来猜测天气情况。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/~Statue+Of+Liberty</span></span></code></pre></div><h3 id="域名所在地的天气" tabindex="-1">域名所在地的天气 <a class="header-anchor" href="#域名所在地的天气" aria-label="Permalink to “域名所在地的天气”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-url.jpg" alt="Weather by domain name from wttr.in"></p><p>你想不想知道 LinuxConfig 托管地的天气？现在有一个方法可以知道！<code>wttr.in</code> 可以通过域名获取天气。是的，这个功能可能不那么实用，但这很有趣啊。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/@linuxconfig.org</span></span></code></pre></div><h3 id="更改温度单位" tabindex="-1">更改温度单位 <a class="header-anchor" href="#更改温度单位" aria-label="Permalink to “更改温度单位”">​</a></h3><p><img src="https://linuxconfig.org/images/wttr-units.jpg" alt="Change unit system in wttr.in"></p><p>默认情况下，<code>wttr.in</code> 会根据你的实际地址来决定显示哪种温度单位（C 还是 F）。基本上，在美国，使用的是华氏度，而其他地方显示的是摄氏度。你可以指定显示的温度单位，在 URL 后添加 <code>?u</code> 会显示华氏度，而添加 <code>?m</code> 会显示摄氏度。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl wttr.in/New_York?m</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ curl wttr.in/Toronto?u</span></span></code></pre></div><p>在 ZSH 上有一个很奇怪的 bug，会使得这两条语句不能正常工作，如果你需要更换单位，恐怕需要改成使用 Bash 了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>你可以很方便地在脚本，定时任务，甚至 MOTD（LCTT 译注：Message Of The Day - 每日消息）中访问 <code>wttr.in</code>。当然，你完全没有必要这么做。当你需要查看天气预报的时候只需要访问一下这个超棒的网站就行了。</p><hr>`,41)),n("p",null,[t[1]||(t[1]=i("via: ",-1)),a(e,{href:"https://linuxconfig.org/get-your-weather-forecast-from-the-linux-cli"},{default:s(()=>[...t[0]||(t[0]=[i("https://linuxconfig.org/get-your-weather-forecast-from-the-linux-cli",-1)])]),_:1})]),n("p",null,[t[5]||(t[5]=i("作者：",-1)),a(e,{href:"https://linuxconfig.org"},{default:s(()=>[...t[2]||(t[2]=[i("Nick Congleton",-1)])]),_:1}),t[6]||(t[6]=i(" 译者：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[3]||(t[3]=[i("lujun9972",-1)])]),_:1}),t[7]||(t[7]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[i("LCTT",-1)])]),_:1}),t[11]||(t[11]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[i("Linux中国",-1)])]),_:1}),t[12]||(t[12]=i(" 荣誉推出",-1))])])}const w=r(h,[["render",g]]);export{C as __pageData,w as default};
